using System;using System.IO;using System.IO.Compression;using System.Linq;using System.Reflection;using System.Security.Cryptography;using System.Text;using System.Diagnostics;using BabelManager;
class SelfUpdateTests {
 static int passed;static void Check(bool ok,string m){if(!ok)throw new Exception(m);passed++;Console.WriteLine("PASS "+m);}
 static object Call(Type type,string method,params object[] args){var member=type.GetMethod(method);if(member==null)throw new Exception("expected feature missing: "+method);try{return member.Invoke(null,args);}catch(TargetInvocationException e){System.Runtime.ExceptionServices.ExceptionDispatchInfo.Capture(e.InnerException).Throw();throw;}}
 static void Reject(Action action,string m){bool rejected=false;try{action();}catch{rejected=true;}Check(rejected,m);}
 static string Hash(string path){using(var hash=SHA256.Create())using(var stream=File.OpenRead(path))return BitConverter.ToString(hash.ComputeHash(stream)).Replace("-","").ToLowerInvariant();}
 static object Release(string tag,string name,string digest,long size,bool draft=false,string url=null){return new{tag_name=tag,prerelease=true,draft=draft,body="launcher release",published_at="2026-10-05T10:00:00Z",html_url="https://github.com/alloywr147/BabelTowerLauncher/releases/tag/"+tag,assets=new[]{new{name=name,size=size,browser_download_url=url??"https://github.com/alloywr147/BabelTowerLauncher/releases/download/"+tag+"/"+name,digest=digest}}};}
 static OfficialRelease Select(params object[] releases){return (OfficialRelease)Call(typeof(OfficialUpdates),"SelectLauncher",Core.Json().Serialize(releases));}
