  using(var f=new Fixture(args[0])){File.Copy(args[0],Path.Combine(f.Target,f.ExeName),true);File.WriteAllText(Path.Combine(f.Target,f.ExeName+".config"),"<configuration/>");File.WriteAllText(Path.Combine(f.Payload,"巴别塔启动器.exe.config"),"<configuration/>");f.Refresh();File.Copy(args[1],Path.Combine(f.Target,"tools","BabelTowerUpdater.exe"));File.Copy(args[1]+".config",Path.Combine(f.Target,"tools","BabelTowerUpdater.exe.config"));string gate=Path.Combine(f.Root,"exit-parent.txt");using(var parent=Process.Start(new ProcessStartInfo(Path.Combine(f.Target,f.ExeName),Core.Quote(gate)){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden,WorkingDirectory=f.Target})){try{var plan=(SelfUpdatePlan)Call(updater,"Prepare",f.Release,f.Zip,f.Target,f.ExeName,parent.Id);Call(updater,"Start",plan);Check(File.Exists(Path.Combine(plan.JobDirectory,"ready.txt"))&&!parent.HasExited,"helper handoff waits for verified readiness before parent exits");Check(!File.Exists(Path.Combine(f.Target,"restart-marker.txt"))&&File.ReadAllText(Path.Combine(f.Target,"assets","app.ico"))=="old icon","helper cannot replace files while parent remains running");File.WriteAllText(gate,"exit");parent.WaitForExit(10000);string marker=Path.Combine(f.Target,"restart-marker.txt");var wait=Stopwatch.StartNew();while(!File.Exists(marker)&&wait.ElapsedMilliseconds<10000)System.Threading.Thread.Sleep(50);Check(File.Exists(marker)&&File.ReadAllText(Path.Combine(plan.JobDirectory,"result.txt")).Trim() == "SUCCESS","background helper replaces isolated fixture after exit and automatically reopens it");Check(File.ReadAllText(Path.Combine(f.Target,"data","settings.json"))=="personal settings","full helper handoff preserves fixture user settings");System.Threading.Thread.Sleep(200);}finally{if(!parent.HasExited){File.WriteAllText(gate,"exit");parent.WaitForExit(10000);}}}}
  using(var f=new Fixture(args[0])){File.Copy(args[0],Path.Combine(f.Target,f.ExeName),true);File.WriteAllText(Path.Combine(f.Target,f.ExeName+".config"),"<configuration/>");File.WriteAllText(Path.Combine(f.Payload,"巴别塔启动器.exe.config"),"<configuration/>");f.Refresh();File.Copy(args[1],Path.Combine(f.Target,"tools","BabelTowerUpdater.exe"));File.Copy(args[1]+".config",Path.Combine(f.Target,"tools","BabelTowerUpdater.exe.config"));string gate=Path.Combine(f.Root,"exit-parent.txt");using(var parent=Process.Start(new ProcessStartInfo(Path.Combine(f.Target,f.ExeName),Core.Quote(gate)){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden})){try{var plan=SelfUpdater.Prepare(f.Release,f.Zip,f.Target,f.ExeName,parent.Id);using(var token=new System.Threading.CancellationTokenSource()){token.Cancel();Reject(()=>SelfUpdater.StartCancelable(plan,token.Token),"cancelled handoff never starts a background updater");Check(String.IsNullOrEmpty(plan.HelperExecutable),"pre-handoff cancellation does not create executable helper copy");}SelfUpdater.Start(plan);SelfUpdater.CancelHandoff(plan);foreach(var helper in Process.GetProcessesByName(Path.GetFileNameWithoutExtension(plan.HelperExecutable)))using(helper){Check(helper.WaitForExit(5000),"cancel after readiness stops helper before any replacement");}Check(!parent.HasExited&&File.ReadAllText(Path.Combine(f.Target,"assets","app.ico"))=="old icon","cancelled handoff leaves parent open and original files unchanged");File.WriteAllText(gate,"exit");parent.WaitForExit(10000);Check(!File.Exists(Path.Combine(f.Target,"restart-marker.txt"))&&!File.Exists(Path.Combine(plan.JobDirectory,"result.txt")),"later parent exit cannot resume a cancelled self-update");}finally{if(!parent.HasExited){File.WriteAllText(gate,"exit");parent.WaitForExit(10000);}}}}
  Console.WriteLine("SELF UPDATE RESULT "+passed+" passed; only isolated silent fixtures launched");
 }catch(Exception e){Console.WriteLine("FAIL "+e);Environment.ExitCode=1;}}
